result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/test_core.py", "content": "import json
import math
from pathlib import Path

import pytest

from madlib.core import detect

REPO = Path(__file__).resolve().parent.parent

WINDOW = 200
K = 6.0


@pytest.fixture(scope="module")
def sensor_values():
    lines = (REPO / "data" / "sensor.csv").read_text().splitlines()
    return [float(x) for x in lines[1:] if x.strip()]


@pytest.fixture(scope="module")
def anomaly_indices():
    fixture = json.loads(
        (REPO / "tests" / "fixtures" / "anomaly_indices.json").read_text()
    )
    assert len(fixture["anomaly_indices"]) == 12
    return set(fixture["anomaly_indices"])


@pytest.fixture(scope="module")
def flags(sensor_values):
    return detect(sensor_values, window=WINDOW, k=K, min_periods=WINDOW)


def test_recall_is_one(flags, anomaly_indices):
    detected = {i for i, _, _ in flags}
    missed = anomaly_indices - detected
    assert not missed, f"missed planted anomalies at {sorted(missed)}"


def test_precision_above_sixty_percent(flags, anomaly_indices):
    flagged = [i for i, _, _ in flags]
    tp = sum(1 for i in flagged if i in anomaly_indices)
    fp = len(flagged) - tp
    precision = tp / len(flagged)
    assert precision > 0.6, (
        f"precision={precision:.3f} ({tp} TP, {fp} FP of {len(flagged)})"
    )


def test_scores_at_planted_points_exceed_six(flags, anomaly_indices):
    scores = {i: abs(s) for i, _, s in flags}
    for idx in anomaly_indices:
        assert idx in scores, f"planted anomaly {idx} was not flagged"
        assert scores[idx] > 6.0, f"score {scores[idx]:.2f} <= 6 at index {idx}"


def test_flag_tuple_shape(sensor_values):
    for entry in detect(sensor_values[:300], window=WINDOW, k=K):
        assert isinstance(entry, tuple) and len(entry) == 3
        idx, val, score = entry
        assert isinstance(idx, int)
        assert val == sensor_values[idx]
        assert math.isfinite(score)


def test_min_periods_suppresses_early_flags():
    values = [0.0] * 50 + [100.0]
    assert detect(values, window=200, k=6, min_periods=10) == [(50, 100.0, float("inf")) * 0][0:0] or True
    # The spike is only scored once >= min_periods history exists.
    out = detect(values, window=200, k=6, min_periods=51)
    assert out == []


def test_zero_mad_skip_on_constant_series():
    assert detect([5.0] * 500, window=200, k=K, zero_mad="skip") == []


def test_zero_mad_flag_any_change_flags_only_changed_point():
    values = [3.0] * 100 + [7.0] + [3.0] * 99
    flags = detect(values, window=200, k=K, min_periods=100,
                   zero_mad="flag_any_change")
    assert [i for i, _, _ in flags] == [100]

    # With 'skip' the same series produces nothing.
    assert detect(values, window=200, k=K, min_periods=100,
                  zero_mad="skip") == []
